import { render } from '@solidjs/web';
import { createSignal, createProjection, For } from 'solid-js';
import './styles.css';

const rows = Array.from({ length: 1000 }, (_, i) => ({ id: i, label: `Row ${i}` }));

function Table() {
  const [selected, setSelected] = createSignal(0);
  const isSelected = (id) => {
    console.count('check');
    return selected() === id;
  };

  return (
    <ul>
      <For each={rows}>
        {(row) => (
          <li class={{ active: isSelected(row.id) }} onClick={() => setSelected(row.id)}>
            {row.label}
          </li>
        )}
      </For>
    </ul>
  );
}

render(() => <Table />, document.getElementById('app'));

ul {
  height: 300px;
  overflow: auto;
  padding: 0;
  font-family: sans-serif;
}

li {
  list-style: none;
  padding: 2px 8px;
  cursor: pointer;
}

li.active {
  background: #446b9e;
  color: white;
}

import { render } from '@solidjs/web';
import { createSignal, createProjection, For } from 'solid-js';
import './styles.css';

const rows = Array.from({ length: 1000 }, (_, i) => ({ id: i, label: `Row ${i}` }));

function Table() {
  const [selected, setSelected] = createSignal(0);
  let previous;
  const selection = createProjection((draft) => {
    console.count('check');
    const id = selected();
    if (previous !== undefined) delete draft[previous];
    draft[id] = true;
    previous = id;
  }, {});

  return (
    <ul>
      <For each={rows}>
        {(row) => (
          <li class={{ active: !!selection[row.id] }} onClick={() => setSelected(row.id)}>
            {row.label}
          </li>
        )}
      </For>
    </ul>
  );
}

render(() => <Table />, document.getElementById('app'));

ul {
  height: 300px;
  overflow: auto;
  padding: 0;
  font-family: sans-serif;
}

li {
  list-style: none;
  padding: 2px 8px;
  cursor: pointer;
}

li.active {
  background: #446b9e;
  color: white;
}
